import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

public class Ex09LazyLoading {

    interface Dept {
        String getName();

        int getUserCount();
    }

    static class DeptImpl implements Dept {
        private final String name;
        private final int count;

        DeptImpl(String name, int count) {
            this.name = name;
            this.count = count;
        }

        public String getName() {
            return name;
        }

        public int getUserCount() {
            return count;
        }
    }

    static class QueryCounter {
        int n = 0;
        final List<String> log = new ArrayList<String>();
    }

    // 延迟加载：getDept() 只返回代理桩，真正发 SQL 要等到调用代理的方法
    static class User {
        private final int id;
        private final int deptId;
        private final QueryCounter counter;
        private Dept deptProxy;

        User(int id, int deptId, QueryCounter counter) {
            this.id = id;
            this.deptId = deptId;
            this.counter = counter;
        }

        Dept getDept() {
            if (deptProxy == null) {
                deptProxy = buildLazyProxy();
            }
            return deptProxy;
        }

        private Dept buildLazyProxy() {
            final boolean[] loaded = new boolean[1];
            final Dept[] target = new Dept[1];
            return (Dept) Proxy.newProxyInstance(
                    Dept.class.getClassLoader(),
                    new Class<?>[] { Dept.class },
                    new InvocationHandler() {
                        public Object invoke(Object proxy, Method method, Object[] args)
                                throws Throwable {
                            if (!loaded[0]) {
                                loaded[0] = true;
                                counter.n++;
                                counter.log.add("SELECT * FROM dept WHERE id = " + deptId);
                                target[0] = new DeptImpl("D" + deptId, deptId * 10);
                            }
                            return method.invoke(target[0], args);
                        }
                    });
        }
    }

    public static void main(String[] args) throws Exception {
        QueryCounter counter = new QueryCounter();
        List<User> users = new ArrayList<User>();
        for (int i = 1; i <= 5; i++) {
            users.add(new User(i, i, counter));
        }
        System.out.println("users built    : " + users.size());
        System.out.println("queries at load: " + counter.n);

        User u1 = users.get(0);
        u1.getDept();
        System.out.println("after getDept() : " + counter.n);

        System.out.println("u1.dept.name   : " + u1.getDept().getName());
        System.out.println("queries now    : " + counter.n);
        System.out.println("u1.dept.count  : " + u1.getDept().getUserCount());
        System.out.println("queries again  : " + counter.n);
        System.out.println("u2.dept.name   : " + users.get(1).getDept().getName());
        System.out.println("queries total  : " + counter.n);
        System.out.println("lazy ok        : " + (counter.n == 2));
        System.out.println("sql log        : " + counter.log);

        QueryCounter eager = new QueryCounter();
        for (int i = 1; i <= 5; i++) {
            eager.n++;
        }
        System.out.println("eager queries  : " + eager.n);
    }
}
